CREATE TABLE public.app_users (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    active boolean NOT NULL,
    assigned_village character varying(255),
    email character varying(255),
    full_name character varying(120) NOT NULL,
    health_centre_id bigint,
    password_hash character varying(255) NOT NULL,
    phone character varying(255),
    role character varying(30) NOT NULL,
    username character varying(60) NOT NULL,
    CONSTRAINT app_users_role_check CHECK (((role)::text = ANY ((ARRAY['ADMIN'::character varying, 'DOCTOR'::character varying, 'HEALTH_WORKER'::character varying, 'PHARMACIST'::character varying, 'SANITATION_OFFICER'::character varying])::text[])))
);
